-- ============================================
-- LUMA — Thème 9 : LONG 2/3 x4 — Une trahison au sein du groupe à gérer
-- ============================================


update scenarios set content = '{"characters": {"thorne": "Thorne", "lyra": "Lyra", "gamemaster": "le maître du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "You find a coded letter in Thorne''s pack while searching for supplies. It bears the enemy''s seal.", "text_fr": "Vous trouvez une lettre codée dans le sac de Thorne en cherchant des provisions. Elle porte le sceau de l''ennemi.", "choices": [{"text": "(Confront Thorne immediately about what you found.)", "text_fr": "(Confronte Thorne immédiatement à propos de ce que tu as trouvé.)", "next": "n2"}, {"text": "(Say nothing for now, but watch Thorne closely.)", "text_fr": "(Ne dis rien pour l''instant, mais surveille Thorne de près.)", "next": "n2b"}]}, "n2": {"speaker": "thorne", "text": "(Freezes, seeing the letter in your hand) ...You weren''t supposed to find that.", "text_fr": "(Se fige, voyant la lettre dans ta main) ...Tu n''étais pas censé trouver ça.", "choices": [{"text": "So it''s true. Why, Thorne? We trusted you.", "text_fr": "Alors c''est vrai. Pourquoi, Thorne ? On te faisait confiance.", "next": "n3"}]}, "n2b": {"speaker": "gamemaster", "text": "(Over the next day, you notice Thorne slipping away at odd moments, always with excuses.)", "text_fr": "(Au cours du jour suivant, vous remarquez Thorne s''éclipsant à des moments étranges, toujours avec des excuses.)", "choices": [{"text": "(Follow Thorne quietly during one of these disappearances.)", "text_fr": "(Suis Thorne discrètement pendant une de ces disparitions.)", "next": "n3"}]}, "n3": {"speaker": "thorne", "text": "(Caught, sighs heavily) They have my sister. I had no choice but to spy for them.", "text_fr": "(Pris sur le fait, soupire lourdement) Ils ont ma sœur. Je n''avais pas le choix, je devais espionner pour eux.", "choices": [{"text": "Your sister? Why didn''t you tell us? We could have helped.", "text_fr": "Ta sœur ? Pourquoi tu ne nous l''as pas dit ? On aurait pu aider.", "next": "n4"}, {"text": "That doesn''t excuse betraying this party, Thorne. People could have died.", "text_fr": "Ça n''excuse pas de trahir ce groupe, Thorne. Des gens auraient pu mourir.", "next": "n4b"}]}, "n4": {"speaker": "thorne", "text": "(Voice breaks) I was afraid... afraid you''d think exactly what you''re thinking now.", "text_fr": "(Voix se brise) J''avais peur... peur que vous pensiez exactement ce que vous pensez maintenant.", "choices": [{"text": "We''re a team, Thorne. We could have found another way, together.", "text_fr": "On est une équipe, Thorne. On aurait pu trouver une autre voie, ensemble.", "next": "n5"}]}, "n4b": {"speaker": "thorne", "text": "(Defensive) You think I wanted this?! I had no choice, don''t you understand?!", "text_fr": "(Sur la défensive) Tu crois que je voulais ça ?! J''avais pas le choix, tu comprends pas ?!", "choices": [{"text": "(Soften) I''m trying to understand. But I need you to be honest with me now.", "text_fr": "(S''adoucit) J''essaie de comprendre. Mais j''ai besoin que tu sois honnête avec moi maintenant.", "next": "n5"}]}, "n5": {"speaker": "lyra", "text": "(Arrives, having overheard) Wait — his sister? This changes things significantly.", "text_fr": "(Arrive, ayant entendu) Attendez — sa sœur ? Ça change les choses considérablement.", "choices": [{"text": "It does. The question now is what we do about it.", "text_fr": "En effet. La question maintenant c''est ce qu''on fait à ce sujet.", "next": "n6"}]}, "n6": {"speaker": "thorne", "text": "(Desperate) Please — help me save her, and I''ll do anything to make this right.", "text_fr": "(Désespéré) S''il vous plaît — aidez-moi à la sauver, et je ferai n''importe quoi pour réparer ça.", "choices": [{"text": "We''ll help you save her. But you need to fully trust us from now on.", "text_fr": "On va t''aider à la sauver. Mais tu dois nous faire pleinement confiance à partir de maintenant.", "next": "n7"}, {"text": "(Turn to Lyra) What do you think — can we really trust him again?", "text_fr": "(Te tournes vers Lyra) Qu''est-ce que tu en penses — on peut vraiment lui refaire confiance ?", "next": "n7b"}]}, "n7": {"speaker": "thorne", "text": "(Relieved, tears welling) Thank you. I swear, I''ll prove my loyalty from here on.", "text_fr": "(Soulagé, larmes montant) Merci. Je jure que je vais prouver ma loyauté à partir de maintenant.", "choices": [{"text": "Then let''s move quickly. Where are they holding your sister?", "text_fr": "Alors avançons vite. Où retiennent-ils ta sœur ?", "next": "n8"}]}, "n7b": {"speaker": "lyra", "text": "(Considers) People do desperate things for family. I say we give him this one chance.", "text_fr": "(Réfléchit) Les gens font des choses désespérées pour la famille. Je dis qu''on lui donne cette chance.", "choices": [{"text": "Agreed. Thorne, where are they holding your sister?", "text_fr": "D''accord. Thorne, où retiennent-ils ta sœur ?", "next": "n8"}]}, "n8": {"speaker": "thorne", "text": "In the enemy stronghold, three days'' march from here. I can lead you there.", "text_fr": "Dans la forteresse ennemie, à trois jours de marche d''ici. Je peux vous y mener.", "choices": [{"text": "Then let''s move immediately. Every hour counts for her safety.", "text_fr": "Alors avançons immédiatement. Chaque heure compte pour sa sécurité.", "next": "n9"}]}, "n9": {"speaker": "gamemaster", "text": "(Three days later, the party arrives at the stronghold, ready to rescue Thorne''s sister together.)", "text_fr": "(Trois jours plus tard, le groupe arrive à la forteresse, prêt à sauver la sœur de Thorne ensemble.)", "choices": [{"text": "(Move forward as a united team, trust rebuilt through this shared mission.)", "text_fr": "(Avance en équipe unie, la confiance reconstruite à travers cette mission commune.)", "next": "end_forgiven"}]}, "end_forgiven": {"speaker": "thorne", "text": "Whatever happens in there, know this — you gave me back something I thought I''d lost: trust.", "text_fr": "Quoi qu''il arrive là-dedans, sachez ceci — vous m''avez redonné quelque chose que je pensais avoir perdu : la confiance.", "end": true, "ending_label": "Trahison pardonnée, confiance reconstruite 💔🤝"}}}'::jsonb, is_playable = true
where title = 'Une trahison au sein du groupe à gérer'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
